class Solution {
public:
    int jobScheduling(vector<int>& startTime, vector<int>& endTime, vector<int>& profit) {
        int n = startTime.size();
        vector<tuple<int, int, int>> jobs(n);
        for (int i = 0; i < n; ++i) {
            jobs[i] = {endTime[i], startTime[i], profit[i]};
        }
        sort(jobs.begin(), jobs.end());
        vector<pair<int, int>> dp = {{0, 0}};
        for (const auto& [e, s, p] : jobs) {
            auto it = upper_bound(dp.begin(), dp.end(), make_pair(s, (int)2e9));
            --it;
            int total = it->second + p;
            if (total > dp.back().second) {
                dp.push_back({e, total});
            }
        }
        return dp.back().second;
    }
};

class Solution {
    public int jobScheduling(int[] startTime, int[] endTime, int[] profit) {
        int n = startTime.length;
        int[][] jobs = new int[n][3];
        for (int i = 0; i < n; i++) {
            jobs[i] = new int[]{endTime[i], startTime[i], profit[i]};
        }
        Arrays.sort(jobs, (a, b) -> a[0] - b[0]);
        TreeMap<Integer, Integer> dp = new TreeMap<>();
        dp.put(0, 0);
        for (int[] job : jobs) {
            int e = job[0], s = job[1], p = job[2];
            int cur = dp.floorEntry(s).getValue() + p;
            if (cur > dp.lastEntry().getValue()) {
                dp.put(e, cur);
            }
        }
        return dp.lastEntry().getValue();
    }
}

var jobScheduling = function(startTime, endTime, profit) {
    const n = startTime.length;
    const jobs = [];
    for (let i = 0; i < n; i++) {
        jobs.push([endTime[i], startTime[i], profit[i]]);
    }
    jobs.sort((a, b) => a[0] - b[0]);
    const dp = [[0, 0]];
    for (const [e, s, p] of jobs) {
        let l = 0, r = dp.length - 1, best = 0;
        while (l <= r) {
            const m = Math.floor((l + r) / 2);
            if (dp[m][0] <= s) {
                best = dp[m][1];
                l = m + 1;
            } else {
                r = m - 1;
            }
        }
        const total = best + p;
        if (total > dp[dp.length - 1][1]) {
            dp.push([e, total]);
        }
    }
    return dp[dp.length - 1][1];
};
